@page "/dashboard"
@rendermode InteractiveServer
@using sv_0249eb151dbf4857a68d7f820f64cf2a.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Currently viewing: <strong>@WarehouseState.CurrentWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @CountColorClass">@AlertService.LatestLowStockCount</p>
                <p class="text-muted small">
                    Items below minimum level
                    <br />
                    <em>Refreshes every 10 seconds</em>
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-8">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Status</h5>
                <ul class="list-unstyled mb-0">
                    <li>⏱️ Polling: <strong class="text-success">Active</strong></li>
                    <li>🏭 Warehouse: <strong>@WarehouseState.CurrentWarehouseId</strong></li>
                    <li>🔄 Last refresh: <strong>@_lastRefresh?.ToString("HH:mm:ss")</strong></li>
                </ul>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private DateTime? _lastRefresh;

    private string CountColorClass => AlertService.LatestLowStockCount switch
    {
        > 10 => "text-danger",
        > 5 => "text-warning",
        _ => "text-success"
    };

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await PollOnceAsync();
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts?.Cancel();
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _ = Task.Run(async () =>
        {
            using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            while (await timer.WaitForNextTickAsync(token))
            {
                await PollOnceAsync();
            }
        }, token);
    }

    private async Task PollOnceAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        _lastRefresh = DateTime.Now;
        // Publish notifies ALL subscribers (sidebar badge + this page)
        AlertService.PublishNewCount(count);
    }

    private void OnWarehouseChanged()
    {
        // Restart polling for the new warehouse immediately
        InvokeAsync(async () =>
        {
            await PollOnceAsync();
            StartPolling();
            StateHasChanged();
        });
    }

    private void OnAlertChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertChanged;
    }
}

